         "values": [
          12,
          28,
          6,
          3
         ]
        },
        {
         "name": "2025",
         "values": [
          46,
          71,
          19,
          8
         ]
        }
       ]
      }
     },
     "task2": {
      "prompt": "Some people believe that universities should focus on providing practical skills for the workplace, while others think the main purpose of higher education is to develop critical thinking and knowledge for its own sake. Discuss both views and give your own opinion. Write at least 250 words."
     }
