  {
   "id": "a1-to-be",
   "title": "The Verb 'To Be'",
   "level": "A1",
   "unit": "First Steps",
   "summary": "am, is, are: saying who you are, where you are and how you feel.",
   "explanation": "'To be' is the most important verb in English.\nI am · you are · he/she/it is · we are · they are.\nShort forms (contractions) are normal in speech: I'm, you're, he's, she's, it's, we're, they're.\nNegative: add 'not': I'm not, he isn't (is not), they aren't (are not).\nQuestions: put the verb first: 'Are you a student?' 'Is she from Toronto?' Short answers: 'Yes, I am.' 'No, she isn't.'\nFrench speakers: age uses 'to be', not 'have': 'I am 30' (NOT *I have 30 years). Also: 'I am hungry / cold / right / afraid' (j'ai faim / froid / raison / peur).",
   "explanation_fr": "Âge, faim, froid, raison, peur : on utilise 'to be' en anglais. « J'ai 30 ans » = I am 30.",
   "examples": [
    {
     "en": "I'm Arnaud. I'm from Montréal.",
     "note": "Introducing yourself."
    },
    {
     "en": "She isn't at home. She's at work.",
     "note": "Negative + location."
    },
    {
     "en": "Are they your colleagues? — Yes, they are.",
     "note": "Question and short answer."
    },
    {
     "en": "I'm 35 years old.",
     "note": "Age with 'to be'."
    }
   ],
   "exercises": [
    {
     "id": "a1-to-be-tb1",
     "type": "mcq",
     "prompt": "My brother ___ a teacher.",
     "options": [
      "am",
      "is",
      "are",
      "be"
     ],
     "answer": "is",
     "explanation": "he/she/it → is."
    },
    {
     "id": "a1-to-be-tb2",
     "type": "mcq",
     "prompt": "___ you from Canada?",
     "options": [
      "Is",
      "Am",
      "Are",
      "Do"
     ],
     "answer": "Are",
     "explanation": "Questions with 'you' → Are you…?"
    },
