"""Generic mock-exam engine for TOEFL iBT (2026 format) and Cambridge C1/C2 practice papers.

All scores are PRACTICE ESTIMATES, never official results.
"""
from __future__ import annotations

from datetime import datetime

from fastapi import APIRouter, Depends, HTTPException, Request
from pydantic import BaseModel, Field
from sqlalchemy.orm import Session

from .. import content
from ..db import get_db
from ..deps import current_profile, provider_errors
from ..models import ActivityLog, ExamAttempt, Profile
from ..providers.llm import ChatMessage, get_llm
from ..providers.speech import fluency_metrics, transcribe_any
from ..services import scales
from ..services.alignment import align

router = APIRouter(prefix="/api/papers", tags=["papers"])
DISCLAIMER = "Practice estimate generated by English Mastery AI. It is not an official ETS or Cambridge result."
SKILL = {"reading": "reading", "listening": "listening", "writing": "writing", "speaking": "speaking"}


def _paper(pid: str) -> dict:
    p = content.by_id(content.papers(), pid)
    if not p:
        raise HTTPException(404, "Paper not found")
    return p


def _section(paper: dict, sid: str) -> dict:
    s = next((s for s in paper["sections"] if s["id"] == sid), None)
    if not s:
        raise HTTPException(404, "Section not found")
    return s


def _strip(part: dict) -> dict:
    """Remove answers before sending a part to the browser."""
    p = {k: v for k, v in part.items() if k not in ("gaps", "questions", "items")}
    if "gaps" in part:
        p["gaps"] = {k: {kk: vv for kk, vv in g.items() if kk != "answer"} for k, g in part["gaps"].items()}
    if "questions" in part:
        p["questions"] = [{k: v for k, v in q.items() if k not in ("answer", "explanation")} for q in part["questions"]]
    if "items" in part:
        p["items"] = [{k: v for k, v in it.items() if k != "answer"} for it in part["items"]]
    return p


@router.get("")
def list_papers():
    return [{"id": p["id"], "kind": p["kind"], "title": p["title"], "intro": p["intro"],
             "sections": [{"id": s["id"], "name": s["name"], "minutes": s["minutes"]} for s in p["sections"]]} for p in content.papers()]


@router.get("/{pid}")
def get_paper(pid: str):
    p = _paper(pid)
    return {**{k: v for k, v in p.items() if k != "sections"}, "disclaimer": DISCLAIMER,
            "sections": [{**{k: v for k, v in s.items() if k != "parts"}, "parts": [_strip(pt) for pt in s["parts"]]} for s in p["sections"]]}


@router.post("/{pid}/attempts")
def start(pid: str, p: Profile = Depends(current_profile), db: Session = Depends(get_db)):
    _paper(pid)
    a = ExamAttempt(profile_id=p.id, exam_id=pid, results={})
    db.add(a)
    db.commit()
    return {"attempt_id": a.id}


def _attempt(db, prof, aid, pid) -> ExamAttempt:
    a = db.get(ExamAttempt, aid)
    if not a or a.profile_id != prof.id or a.exam_id != pid:
        raise HTTPException(404, "Attempt not found")
    if a.finished_at:
        raise HTTPException(409, "This attempt is already finished")
    return a


def _norm(s: str) -> str:
    return content.normalise(s).replace("’", "'")


def score_objective_part(part: dict, answers: dict[str, str]) -> list[dict]:
    """Score one objective part. Keys: '<part>:<gap|question|item id>'."""
    out = []
    pid = part["id"]
    if part["type"] == "gapfill":
        for gid, g in part["gaps"].items():
            given = answers.get(f"{pid}:{gid}", "")
            accepted = g["answer"] if isinstance(g["answer"], list) else [g["answer"]]
            ok = _norm(given) in {_norm(a) for a in accepted}
            if not ok and g.get("prefix"):  # learner may type the whole word for Complete the Words
                ok = _norm(given) in {_norm(g["prefix"] + a) for a in accepted}
            out.append({"key": f"{pid}:{gid}", "correct": ok, "given": given, "answer": accepted[0]})
    elif part["type"] == "mcq":
        for q in part["questions"]:
            given = answers.get(f"{pid}:{q['id']}", "")
            out.append({"key": f"{pid}:{q['id']}", "correct": _norm(given) == _norm(q["answer"]), "given": given,
                        "answer": q["answer"], "explanation": q.get("explanation", ""), "prompt": q["prompt"]})
    elif part["type"] in ("transform", "build_sentence"):
        for it in part["items"]:
            given = answers.get(f"{pid}:{it['id']}", "")
            accepted = it["answer"] if isinstance(it["answer"], list) else [it["answer"]]
            ok = _norm(given) in {_norm(a) for a in accepted}
            out.append({"key": f"{pid}:{it['id']}", "correct": ok, "given": given, "answer": accepted[0]})
    return out


class ObjectiveIn(BaseModel):
    answers: dict[str, str]
    seconds: int = Field(0, ge=0, le=14400)


def _save(db, a, sid, result):
    a.results = {**(a.results or {}), sid: result}
    db.commit()


@router.post("/{pid}/attempts/{aid}/sections/{sid}/objective")
def objective(pid: str, aid: int, sid: str, body: ObjectiveIn, p: Profile = Depends(current_profile), db: Session = Depends(get_db)):
    paper = _paper(pid)
    a = _attempt(db, p, aid, pid)
    sec = _section(paper, sid)
    if sec["scoring"] != "objective":
        raise HTTPException(400, "This section is not objectively scored")
    review = [r for part in sec["parts"] for r in score_objective_part(part, body.answers)]
    pct = sum(r["correct"] for r in review) / max(1, len(review))
    result = {"pct": round(pct, 3), "correct": sum(r["correct"] for r in review), "total": len(review),
              "score": scales.section_score(pct, paper["kind"]), "review": review}
    _save(db, a, sid, result)
    db.add(ActivityLog(profile_id=p.id, skill=SKILL.get(sid, "reading"), item_id=f"paper:{pid}:{aid}", score=pct, seconds=body.seconds))
    db.commit()
    return result


WRITING_RUBRIC = {
    "toefl2026": "You are an experienced TOEFL iBT writing rater (2026 format). For each task give a score from 0 to 5 using the ETS rubric for that task type (task completion, development, organisation, language use).",
    "cambridge_c1": "You are a Cambridge C1 Advanced writing examiner. Score each task on the four Cambridge criteria — Content, Communicative Achievement, Organisation, Language — each 0 to 5, and give 'score' as their average.",
    "cambridge_c2": "You are a Cambridge C2 Proficiency writing examiner. Score each task on the four Cambridge criteria — Content, Communicative Achievement, Organisation, Language — each 0 to 5, and give 'score' as their average. For the summary essay, reward accurate summary of BOTH texts in the candidate's own words plus evaluation.",
}


class WritingIn(BaseModel):
    texts: dict[str, str] = Field(default_factory=dict)
    answers: dict[str, str] = Field(default_factory=dict)  # objective writing items (Build a Sentence)
    seconds: int = Field(0, ge=0, le=14400)


@router.post("/{pid}/attempts/{aid}/sections/{sid}/writing")
@provider_errors
def writing(pid: str, aid: int, sid: str, body: WritingIn, p: Profile = Depends(current_profile), db: Session = Depends(get_db)):
    paper = _paper(pid)
    a = _attempt(db, p, aid, pid)
    sec = _section(paper, sid)
    if sec["scoring"] != "writing":
        raise HTTPException(400, "Not a writing section")
    objective_review = [r for part in sec["parts"] if part["type"] == "build_sentence" for r in score_objective_part(part, body.answers)]
    tasks = [t for part in sec["parts"] if part["type"] == "writing" for t in part["tasks"]]
    text = "\n\n".join(f"TASK '{t['id']}' (minimum {t['min_words']} words)\nPROMPT: {t['prompt']}\nANSWER:\n{body.texts.get(t['id']) or '(no answer)'}" for t in tasks)
    r = get_llm().chat_json([
        ChatMessage("system", WRITING_RUBRIC[paper["kind"]] + ' Return strict JSON: {"tasks": {"<task id>": {"score": float, "criteria": {"<name>": float}, '
                    '"feedback": str, "key_errors": [{"original": str, "corrected": str, "explanation": str}]}}, "improvements": [str]}. '
                    "Penalise answers below the minimum length."),
        ChatMessage("user", text),
    ], max_tokens=3000)
    task_pcts = [max(0.0, min(1.0, float((r.get("tasks", {}).get(t["id"]) or {}).get("score") or 0) / 5)) for t in tasks]
    parts = task_pcts + ([sum(x["correct"] for x in objective_review) / len(objective_review)] if objective_review else [])
    pct = sum(parts) / len(parts)
    result = {"pct": round(pct, 3), "score": scales.section_score(pct, paper["kind"]), "tasks": r.get("tasks", {}),
              "improvements": r.get("improvements", []), "objective_review": objective_review}
    _save(db, a, sid, result)
    db.add(ActivityLog(profile_id=p.id, skill="writing", item_id=f"paper:{pid}:{aid}", score=pct, seconds=body.seconds))
    db.commit()
    return result


SPEAKING_PROMPT = {
    "toefl2026": "You are a TOEFL iBT speaking rater (2026 'Take an Interview' task).",
    "cambridge_c1": "You are a Cambridge C1 Advanced speaking examiner (criteria: Grammatical Resource, Lexical Resource, Discourse Management, Pronunciation, Interactive Communication).",
    "cambridge_c2": "You are a Cambridge C2 Proficiency speaking examiner (criteria: Grammatical Resource, Lexical Resource, Discourse Management, Pronunciation, Interactive Communication).",
}


@router.post("/{pid}/attempts/{aid}/sections/{sid}/speaking")
@provider_errors
async def speaking(pid: str, aid: int, sid: str, request: Request, p: Profile = Depends(current_profile), db: Session = Depends(get_db)):
    """Multipart form: one audio file per item, field name = '<part id>:<item id>'.
    Optional 'transcript:<part>:<item>' / 'duration:<part>:<item>' fields carry the browser's own recognition."""
    paper = _paper(pid)
    a = _attempt(db, p, aid, pid)
    sec = _section(paper, sid)
    if sec["scoring"] != "speaking":
        raise HTTPException(400, "Not a speaking section")
    form = await request.form()
    repeat_scores, answers, total = [], [], 0
    for part in sec["parts"]:
        for it in part["items"]:
            up = form.get(f"{part['id']}:{it['id']}")
            data = await up.read() if up is not None and hasattr(up, "read") else b""
            if len(data) > 25 * 1024 * 1024:
                raise HTTPException(413, "Recording too long")
            key = f"{part['id']}:{it['id']}"
            tx = str(form.get(f"transcript:{key}") or "")
            du = float(form.get(f"duration:{key}") or 0)
            t = transcribe_any(data, "speech.webm", tx, du) if (data or tx) else None
            m = fluency_metrics(t) if t else None
            total += int((m or {}).get("duration_sec") or 0)
            if part["type"] == "speaking_repeat":
                al = align(it["text"], t.text if t else "")
                repeat_scores.append({"id": it["id"], "target": it["text"], "heard": t.text if t else "", "score": al["score"], "words": al["words"]})
            else:
                answers.append({"id": it["id"], "question": it["question"], "transcript": t.text if t else "", "metrics": m})
    pcts = []
    if repeat_scores:
        pcts.append(sum(r["score"] for r in repeat_scores) / len(repeat_scores))
    llm_result = None
    if answers:
        if not any(x["transcript"] for x in answers):
            pcts.append(0.0)
        else:
            body = "\n\n".join(f"Q: {x['question']}\nTRANSCRIPT: {x['transcript'] or '(no answer)'}\nMETRICS: {x['metrics']}" for x in answers)
            llm_result = get_llm().chat_json([
                ChatMessage("system", SPEAKING_PROMPT[paper["kind"]] + " Transcripts come from speech recognition (ignore punctuation). "
                            'Return strict JSON: {"score": float (0-5), "criteria": {"<name>": float}, "feedback": str, "strengths": [str], "improvements": [str]}. '
                            "Pronunciation can only be estimated from recognition quality and metrics — say so."),
                ChatMessage("user", body)], max_tokens=1500)
            pcts.append(max(0.0, min(1.0, float(llm_result.get("score") or 0) / 5)))
    if not pcts:
        raise HTTPException(422, "No recordings received")
    pct = sum(pcts) / len(pcts)
    result = {"pct": round(pct, 3), "score": scales.section_score(pct, paper["kind"]), "repeat": repeat_scores,
              "answers": answers, "assessment": llm_result}
    _save(db, a, sid, result)
    db.add(ActivityLog(profile_id=p.id, skill="speaking", item_id=f"paper:{pid}:{aid}", score=pct, seconds=total + 60))
    db.commit()
    return result


@router.post("/{pid}/attempts/{aid}/finish")
def finish(pid: str, aid: int, p: Profile = Depends(current_profile), db: Session = Depends(get_db)):
    paper = _paper(pid)
    a = _attempt(db, p, aid, pid)
    res = a.results or {}
    done = {s["id"]: res[s["id"]]["score"] for s in paper["sections"] if s["id"] in res}
    if not done:
        raise HTTPException(400, "Complete at least one section first.")
    o = scales.overall(list(done.values()), paper["kind"])
    weakest = min(done, key=lambda k: res[k]["pct"])
    summary = {"sections": done, **o, "complete": len(done) == len(paper["sections"]), "weakest": weakest, "disclaimer": DISCLAIMER}
    a.results = {**res, "summary": summary}
    a.overall_band = float(o["overall"])
    a.finished_at = datetime.utcnow()
    db.commit()
    return summary

